import re
import unicodedata

# Pipeline de limpieza completo y reutilizable (el que usará tu PWA)

_CONTROL = re.compile(r'[\x00-\x08\x0e-\x1f\x7f]')          # chars de control (excepto \t \n \r)
_ESPACIOS = re.compile(r'\s+')
_INVISIBLES = re.compile(r'[\u200b-\u200f\u202a-\u202e\ufeff\u00a0]')  # zero-width, BOM, nbsp

def limpiar_texto(texto, *, colapsar=True, case=None, unicode_nfc=True) -> str:
    """Normaliza texto a forma canónica. Nunca lanza por datos raros."""
    if texto is None:
        return ''
    if not isinstance(texto, str):
        texto = str(texto)

    texto = _INVISIBLES.sub('', texto)      # 1. invisibles primero
    texto = _CONTROL.sub('', texto)         # 2. control
    if unicode_nfc:
        texto = unicodedata.normalize('NFC', texto)   # 3. Unicode canónico
    if colapsar:
        texto = _ESPACIOS.sub(' ', texto)   # 4. colapsar whitespace
    texto = texto.strip()                   # 5. extremos

    if case == 'lower':
        texto = texto.lower()
    elif case == 'upper':
        texto = texto.upper()
    elif case == 'title':
        import string
        texto = string.capwords(texto)      # NO .title() (ver M1.4-002)
    return texto

# Normalizadores específicos del dominio
def normalizar_email(email: str) -> str:
    """Gmail ignora puntos y +tags en el local part."""
    local, sep, dominio = limpiar_texto(email, case='lower').partition('@')
    if not sep:
        return email.lower()
    local = local.split('+')[0].replace('.', '')
    return f'{local}@{dominio}'

def normalizar_telefono(tel: str) -> str:
    """Conserva solo dígitos y el + inicial."""
    limpio = re.sub(r'[^\d+]', '', tel)
    return limpio

def slugify(texto: str) -> str:
    """'Aprende Python Ya!' → 'aprende-python-ya' (para URLs de tu PWA)."""
    texto = unicodedata.normalize('NFD', texto.lower())
    texto = ''.join(c for c in texto if unicodedata.category(c) != 'Mn')  # sin acentos
    texto = re.sub(r'[^a-z0-9]+', '-', texto)                             # no alnum → guion
    return texto.strip('-')

# Validación post-limpieza: nunca confíes en la salida sin verificarla
_CAMPOS_REQUERIDOS = ('titulo', 'cuerpo')

def validar_registro(reg: dict) -> list:
    errores = []
    for campo in _CAMPOS_REQUERIDOS:
        if not limpiar_texto(reg.get(campo)):
            errores.append(f'campo vacío o inválido: {campo}')
    if len(reg.get('titulo', '')) > 200:
        errores.append('titulo excede 200 caracteres')
    return errores

# Aplicación en streaming sobre datos sucios:
def limpiar_lotes(registros, tamano=100):
    lote = []
    for reg in registros:
        limpio = {k: limpiar_texto(v) if isinstance(v, str) else v for k, v in reg.items()}
        if not validar_registro(limpio):
            lote.append(limpio)
        if len(lote) >= tamano:
            yield lote
            lote = []
    if lote:
        yield lote

