import re
from html.parser import HTMLParser

# ============ EMAIL: la estrategia en 3 niveles ============

# Nivel 1 — Sintaxis (lo que SÍ debes validar en el cliente):
_EMAIL = re.compile(
    r"^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+"
    r"@([A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+"
    r"[A-Za-z]{2,63}$"
)

def email_sintacticamente_valido(s: str) -> bool:
    if not isinstance(s, str) or not 3 <= len(s) <= 254:
        return False
    local, sep, dominio = s.partition('@')
    if not sep or not local or not dominio or len(local) > 64:
        return False
    if local[0] == '.' or local[-1] == '.' or '..' in local:
        return False
    return bool(_EMAIL.match(s))

# Nivel 2 — Normalización (para detectar duplicados):
def normalizar_email(s: str) -> str:
    local, _, dominio = s.strip().lower().partition('@')
    if dominio in ('gmail.com', 'googlemail.com'):
        local = local.split('+')[0].replace('.', '')
    return f'{local}@{dominio}'

# Nivel 3 — Existencia real: SOLO un correo de confirmación la prueba.
#   Ningún regex, ni una consulta MX, garantiza que el buzón existe.
#   (Una consulta DNS MX verifica el DOMINIO, no la cuenta.)

# ============ HTML: por qué regex es matemáticamente insuficiente ============
# HTML permite anidamiento recursivo:
#   <div><div><div>...</div></div></div>
# Los lenguajes regulares no pueden contar niveles de anidamiento
# (teorema: no son regulares). Por eso NINGÚN regex puede parsear HTML
# correctamente. Y por eso existen parsers.

# Parser genérico reutilizable para tu scraper de la Fase 2
class ExtractorDeEtiquetas(HTMLParser):
    """Extrae texto de cualquier etiqueta, manejando atributos, case,
    multilínea, entidades y comentarios correctamente."""

    def __init__(self, etiquetas=('h2',)):
        super().__init__(convert_charrefs=True)
        self.etiquetas = {e.lower() for e in etiquetas}
        self.resultados = []
        self._pila = []
        self._buffer = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() in self.etiquetas:
            self._pila.append(tag.lower())
            self._buffer = []

    def handle_endtag(self, tag):
        if self._pila and self._pila[-1] == tag.lower():
            self._pila.pop()
            self.resultados.append(''.join(self._buffer).strip())

    def handle_data(self, data):
        if self._pila:
            self._buffer.append(data)

def extraer(html: str, *etiquetas) -> list:
    p = ExtractorDeEtiquetas(etiquetas or ('h2',))
    p.feed(html)
    return p.resultados

# ============ CUÁNDO SÍ usar regex con HTML ============
# Solo sobre HTML que TÚ generaste y cuya forma controlas al 100%,
# para extracciones triviales (quitar etiquetas, extraer un atributo fijo).
_QUITAR_ETIQUETAS = re.compile(r'<[^>]+>')
def solo_texto(html_propio: str) -> str:
    return _QUITAR_ETIQUETAS.sub(' ', html_propio)
