import json
import os
import re
import tempfile

_PRODUCTO = re.compile(
    r'<div\s+class="producto">\s*'
    r'<h3>\s*(?P<nombre>.*?)\s*</h3>\s*'
    r'<span\s+class="precio">\s*\$\s*(?P<precio>[\d.,]+)\s*</span>\s*'
    r'<span\s+class="stock">\s*stock:\s*(?P<stock>\d+)\s*</span>',
    re.DOTALL | re.IGNORECASE,
)

def _limpiar_numero(crudo):
    return float(crudo.replace(',', '').strip())

def extraer_productos(html_texto, ruta_salida):
    productos = []
    for m in _PRODUCTO.finditer(html_texto):
        nombre = re.sub(r'\s+', ' ', m.group('nombre')).strip()
        try:
            precio = _limpiar_numero(m.group('precio'))
            stock = int(m.group('stock'))
        except ValueError:
            continue
        if not nombre:
            continue
        productos.append({'nombre': nombre, 'precio': precio, 'stock': stock})

    dirn = os.path.dirname(os.path.abspath(ruta_salida))
    fd, tmp = tempfile.mkstemp(dir=dirn, suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            json.dump(productos, f, ensure_ascii=False, indent=2)
        os.replace(tmp, ruta_salida)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise
